use std::io::{self, BufRead};

fn to_base(n: u64, base: u64) -> String {
    let digits: Vec<char> = "0123456789abcdef".chars().collect();
    if n == 0 {
        return "0".to_string();
    }
    let mut n = n;
    let mut reversed = String::new();
    while n > 0 {
        reversed.push(digits[(n % base) as usize]);
        n /= base;
    }
    reversed.chars().rev().collect()
}

fn parse_number(text: &str) -> Option<u64> {
    let lower_text = text.to_lowercase();
    let lower: &str = &lower_text;
    let (digits, base) = if let Some(rest) = lower.strip_prefix("0x") {
        (rest, 16)
    } else if let Some(rest) = lower.strip_prefix("0b") {
        (rest, 2)
    } else if let Some(rest) = lower.strip_prefix("0o") {
        (rest, 8)
    } else {
        (lower, 10)
    };
    if digits.is_empty() {
        return None;
    }
    let mut value: u64 = 0;
    for c in digits.chars() {
        let d = c.to_digit(16)? as u64;
        if d >= base {
            return None;
        }
        value = value.checked_mul(base)?.checked_add(d)?;
    }
    Some(value)
}

fn to_roman(n: u32) -> Option<String> {
    if !(1..=3999).contains(&n) {
        return None;
    }
    let mut n = n;
    const TABLE: [(u32, &str); 13] = [
        (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"), (100, "C"), (90, "XC"),
        (50, "L"), (40, "XL"), (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"),
    ];
    let mut out = String::new();
    for (value, symbol) in TABLE {
        while n >= value {
            out.push_str(symbol);
            n -= value;
        }
    }
    Some(out)
}

fn main() {
    for line in io::stdin().lock().lines() {
        let line = line.unwrap();
        let words: Vec<&str> = line.split_whitespace().collect();
        if words.is_empty() {
            continue;
        }
        let command_text = words[0].to_lowercase();
        let command: &str = &command_text;
        if command == "quit" {
            break;
        }
        let known = command == "bin" || command == "hex" || command == "oct" || command == "dec" || command == "roman";
        if !known {
            println!("Unknown command: {}", words[0]);
            continue;
        }
        if words.len() != 2 {
            println!("Usage: {command} <value>");
            continue;
        }
        let value = words[1];
        match command {
            "dec" => match parse_number(value) {
                Some(n) => println!("{value} = {n}"),
                None => println!("Not a number: {value}"),
            },
            "roman" => match value.parse::<u32>() {
                Ok(n) => match to_roman(n) {
                    Some(r) => println!("{n} = {r}"),
                    None => println!("Roman numerals go from 1 to 3999"),
                },
                Err(_) => println!("Not a number: {value}"),
            },
            _ => match value.parse::<u64>() {
                Ok(n) => {
                    let (prefix, base) = match command {
                        "bin" => ("0b", 2),
                        "hex" => ("0x", 16),
                        _ => ("0o", 8),
                    };
                    println!("{n} = {prefix}{}", to_base(n, base));
                }
                Err(_) => println!("Not a number: {value}"),
            },
        }
    }
}
